import{_ as d,o as r,c as a,a as e}from"./chunks/framework.Ld7uezS_.js";const m=JSON.parse('{"title":"核心术语表","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":1787284307000}'),l={name:"glossary.md"};function i(s,t,o,h,f,n){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="核心术语表" tabindex="-1">核心术语表 <a class="header-anchor" href="#核心术语表" aria-label="Permalink to &quot;核心术语表&quot;">​</a></h1><blockquote><p>先用自己的话理解，再回到对应章节学习。术语的法律定义、标准定义和设备界面名称可能不同，遇到争议以现行标准和设备说明书为准。</p></blockquote><table tabindex="0"><thead><tr><th>术语</th><th>零基础解释</th><th>关联页面</th></tr></thead><tbody><tr><td>可燃物</td><td>能够参与燃烧的物质</td><td><a href="/theory/03-combustion-fire">燃烧基础</a></td></tr><tr><td>助燃物/氧化剂</td><td>帮助燃烧反应持续的物质，常见是氧气</td><td><a href="/theory/03-combustion-fire">燃烧基础</a></td></tr><tr><td>引火源</td><td>能给可燃物提供点燃能量的明火、电弧、高温等</td><td><a href="/theory/03-combustion-fire">燃烧基础</a></td></tr><tr><td>火灾报警</td><td>系统报告疑似火情的状态信息</td><td><a href="/skill/01-monitoring">设施监控</a></td></tr><tr><td>故障</td><td>设备、线路、电源或通信可能异常的状态信息</td><td><a href="/skill/04-repair">设施维修</a></td></tr><tr><td>监管报警</td><td>受监管设备或输入状态异常的信息</td><td><a href="/skill/01-monitoring">设施监控</a></td></tr><tr><td>屏蔽/隔离</td><td>设备或功能暂时不参与监视或联动</td><td><a href="/skill/01-monitoring">设施监控</a></td></tr><tr><td>复位</td><td>按程序让设备返回规定初始/监视状态的操作</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>消音</td><td>暂停声响提示，不代表故障或火警已经排除</td><td><a href="/skill/01-monitoring">设施监控</a></td></tr><tr><td>联动</td><td>一个或多个输入条件满足后，控制器按逻辑驱动相关设备</td><td><a href="/theory/06-fire-facilities">消防设施基础</a></td></tr><tr><td>反馈</td><td>被控设备把动作、运行或故障状态返回控制器</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>防火分区</td><td>建筑内部用具有一定耐火能力的构件划出的区域，重点限制火焰、热量和燃烧产物向相邻区域扩大；常涉及防火墙、防火门、防火卷帘和防火封堵</td><td><a href="/theory/04-building-fire">建筑防火</a></td></tr><tr><td>防烟分区</td><td>建筑内部用于控制烟气水平扩散的区域，常与挡烟垂壁、排烟口、排烟风机和加压送风设施配合；重点不是直接阻挡火焰</td><td><a href="/theory/04-building-fire">建筑防火</a></td></tr><tr><td>防火间距</td><td>相邻建筑之间为降低热辐射、飞火和火焰相互蔓延风险而保持的空间距离；不能用建筑内部防火门代替</td><td><a href="/theory/04-building-fire">建筑防火</a></td></tr><tr><td>耐火极限</td><td>针对具体构件或构件组合，在规定标准耐火试验条件下保持承载能力、完整性或隔热性的时间；不是整栋建筑能燃烧的时间</td><td><a href="/theory/04-building-fire">建筑防火</a></td></tr><tr><td>耐火等级</td><td>对建筑整体耐火能力进行分级的概念，通常按一级至四级理解；需要综合主要构件的耐火性能和建筑条件，不能等同于某一个构件的耐火极限</td><td><a href="/theory/04-building-fire">建筑防火</a></td></tr><tr><td>正常监视</td><td>消防系统处于规定的正常工作状态</td><td><a href="/skill/01-monitoring">设施监控</a></td></tr><tr><td>手动状态</td><td>设备需通过人工操作或指定条件启动，不能直接假设会自动联动</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>自动状态</td><td>按设计逻辑和满足条件时自动执行相关动作</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>主电/备电</td><td>正常供电和备用供电来源</td><td><a href="/theory/05-electrical-fire">电气消防</a></td></tr><tr><td>保养</td><td>通过检查、清洁、紧固和功能确认保持设施可用</td><td><a href="/skill/03-maintenance">设施保养</a></td></tr><tr><td>维修</td><td>针对故障进行原因判断、处理和功能恢复</td><td><a href="/skill/04-repair">设施维修</a></td></tr><tr><td>检测</td><td>依据标准、方案和设备说明书验证设施功能并记录结果</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>报警阀组</td><td>自动喷水灭火系统中用于控制、检验和传递相关水流信号的组合部件，具体构成要结合系统形式学习</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>水流指示器</td><td>感知管网中水流并输出区域水流信号的部件，不能单独替代完整的压力或联动判断</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>压力开关</td><td>根据压力变化输出开关信号的部件，常参与消防泵启动或状态反馈，具体逻辑以设计和设备为准</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>末端试水装置</td><td>用于在规定测试点模拟放水并观察相关水流、压力和信号链的装置</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>稳压泵</td><td>用于维持系统规定压力条件的泵组，不能把它与主消防泵的功能混为一谈</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>输入模块</td><td>采集现场触点或状态信号并传回控制器的模块</td><td><a href="/skill/alarm-system">报警系统项目卡</a></td></tr><tr><td>输入/输出模块</td><td>可按系统设计同时完成状态采集和控制输出的模块，具体功能以图纸和设备说明书为准</td><td><a href="/skill/alarm-system">报警系统项目卡</a></td></tr><tr><td>水泵接合器</td><td>供消防车等外部水源向建筑消防给水系统补水或加压使用的接口设施，不能代替系统日常水源</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>正压送风</td><td>通过送风使指定区域保持相对正压、减少烟气进入的防烟方式</td><td><a href="/skill/other-facilities">其他消防设施项目卡</a></td></tr><tr><td>排烟防火阀</td><td>兼具排烟系统气流控制和防火分隔作用的阀类部件，动作温度、联动和复位要求以适用依据为准</td><td><a href="/skill/other-facilities">其他消防设施项目卡</a></td></tr><tr><td>静压</td><td>水或气体基本不流动时在测点表现的压力，不能单独证明流量或供水能力</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>动压</td><td>水或气体流动时测得的压力，会受流量、阻力和高差影响</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>流量</td><td>单位时间通过管道的水量，必须结合测点、仪器和测试条件理解</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>最不利点</td><td>在设计或检测判断中供水、送风或排烟条件相对不利、需要重点核对的部位</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>检查</td><td>通过观察、核对资料或确认状态发现明显异常的活动</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>测量</td><td>使用仪器取得某测点客观读数的活动</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>试验</td><td>按方案触发或模拟设备动作，观察系统响应的活动</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>判定</td><td>将检查、测量和试验结果与适用依据比较后形成结论</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>原始记录</td><td>未经删改的现场时间、对象、条件、读数、动作和现象记录</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>复测</td><td>处理异常后按原依据或批准方法重新检查、测量或试验</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>消防电梯</td><td>供消防人员灭火救援使用的专用电梯及其相关控制、供电和接口系统</td><td><a href="/skill/other-facilities">其他消防设施项目卡</a></td></tr><tr><td>应急广播</td><td>在火灾等应急状态下向指定区域传递疏散和处置信息的广播系统</td><td><a href="/skill/other-facilities">其他消防设施项目卡</a></td></tr><tr><td>消防电话</td><td>用于消防控制室与现场电话分机之间应急通信的系统</td><td><a href="/skill/other-facilities">其他消防设施项目卡</a></td></tr><tr><td>任务识别</td><td>先确认任务是查询、控制、测试、恢复还是交接报告，再决定操作范围、授权和记录要求</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>操作对象</td><td>本次任务真正针对的输入设备、控制设备、执行设备或反馈点，不能只写“某系统”</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>保护区域</td><td>由建筑位置、分区、设备地址和图纸共同确定的系统保护范围</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>完成标准</td><td>判断任务是否收口所需的显示、动作、反馈、测量或恢复证据</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>任务复述</td><td>用“位置—对象—动作—目的—预期—恢复”重新说一遍任务，避免误操作</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>回路</td><td>控制器与一组现场设备之间组织通信或供电/通信的线路单元，用于判断异常影响范围</td><td><a href="/skill/alarm-system">报警系统项目卡</a></td></tr><tr><td>设备地址</td><td>同一回路中区分某个现场设备的编号或标识，不能替代建筑区域名称</td><td><a href="/skill/alarm-system">报警系统项目卡</a></td></tr><tr><td>控制阀</td><td>改变消防给水管网通断或分区状态的阀门，操作必须有授权和恢复责任</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>水力证据</td><td>水位、压力、流量、出水和排水等反映供水过程的现场证据</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>反馈证据</td><td>现场设备把运行、到位或故障状态返回控制器的证据，不能与现场动作混同</td><td><a href="/skill/alarm-system">报警系统项目卡</a></td></tr><tr><td>五项结果</td><td>检测时依次记录输入/触发、控制器显示、现场动作、反馈和恢复，用于避免把局部现象写成完整结论</td><td><a href="/skill/alarm-system">报警系统项目卡</a></td></tr><tr><td>水力证据链</td><td>从水源、阀门、泵组、管网、测点到出水和排水的连续证据，用于判断供水过程是否成立</td><td><a href="/skill/water-system">水系统项目卡</a></td></tr><tr><td>到位反馈</td><td>现场执行机构达到规定位置后返回控制器的状态信息</td><td><a href="/skill/02-operation">设施操作</a></td></tr><tr><td>校准/检定状态</td><td>说明仪器是否在规定周期、范围和条件下可用于相应测量，具体要求依仪器类别和管理制度</td><td><a href="/skill/05-detection">设施检测</a></td></tr><tr><td>关键技能（★）</td><td>标准中涉及安全生产或核心操作的技能项目</td><td><a href="/skill-roadmap">技能路线图</a></td></tr></tbody></table>',3)])])}const c=d(l,[["render",i]]);export{m as __pageData,c as default};
